inline std::string binary_sha(){std::vector<wchar_t> path(32768);auto n=GetModuleFileNameW(nullptr,path.data(),DWORD(path.size()));if(!n||n==path.size())throw std::runtime_error("current executable path");return s1::sha_file(std::filesystem::path(std::wstring(path.data(),n)));}
using udriver::Record;using udriver::Domain;using udriver::Bundle;using udriver::Step;using udriver::PhaseSegment;
inline constexpr Domain domain{1891716,2678400};
inline constexpr const char* source_sha="8914c691dc39f0f425ade34d34789e2b1985a9434fe31d1300bccb79a641c81c";
inline constexpr const char* protocol_sha="6a68de0ff20a438937251ca2a0aab1830824d0bdd2ef642985730c73d55ee181";
inline std::filesystem::path protocol_path(){return std::filesystem::u8path(__FILE__).parent_path().parent_path()/"s2_protocol.json";}
inline std::string quote(const std::string& s){std::string o="\"";for(char c:s){if(c=='\\'||c=='\"')o+='\\';if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else o+=c;}return o+'\"';}
inline std::string record_sha(const std::vector<Record>& v){s1::SHA256 h;for(auto r:v){h.u64(r.first);h.u64(r.second);}return h.finish();}
inline std::uint64_t query_hash(const Bundle& b){auto h=udriver::phase_hash_basis;for(const auto& st:b.whole.steps)if(st.query)h=udriver::mix(h,st.expected_hash);return h;}
inline void validate_profile(const std::string& p,unsigned seed){if(!((p=="engineering"&&(seed==102001||seed==102002))||(p=="final"&&seed>=100001&&seed<=100010)||(p=="aa"&&seed==101001)))throw std::invalid_argument("S2 seed/profile rejected");}
inline void validate_case(const std::string& id){if(id!="L01"&&id!="L02"&&id!="L03")throw std::invalid_argument("S2 case rejected");}
class Fenwick {
 std::vector<std::int64_t> tree_;std::int64_t count_=0;
public:
 explicit Fenwick(std::size_t n):tree_(n+1){}
 void add(std::size_t pos,int delta){if(pos+1>=tree_.size())throw std::out_of_range("alive position");count_+=delta;for(++pos;pos<tree_.size();pos+=pos&(~pos+1))tree_[pos]+=delta;}
 std::size_t select(std::size_t rank)const{if(rank>=std::size_t(count_))throw std::out_of_range("current-live rank");std::size_t pos=0,bit=1;while(bit<tree_.size())bit<<=1;for(;bit;bit>>=1){auto next=pos+bit;if(next<tree_.size()&&tree_[next]<=std::int64_t(rank)){rank-=std::size_t(tree_[next]);pos=next;}}return pos;}
 std::size_t size()const{return std::size_t(count_);}
};
inline void valid_record(Record r){if(!r.second||r.second>=domain.stride||r.first/domain.stride>=domain.span||r.first%domain.stride!=r.second)throw std::runtime_error("NASA encoded identity/domain mismatch");}
inline std::vector<Record> load_timestamps(const std::filesystem::path& p,const std::string& sha){if(sha!=source_sha)throw std::invalid_argument("unregistered source hash");s1::require_sha(p,sha);std::ifstream in(p,std::ios::binary);char magic[8];in.read(magic,8);if(!in||std::memcmp(magic,"S2TIME01",8))throw std::runtime_error("NASA projection magic");auto read=[&](){unsigned char b[8];in.read(reinterpret_cast<char*>(b),8);if(!in)throw std::runtime_error("NASA projection truncated");std::uint64_t n=0;for(unsigned j=0;j<8;++j)n|=std::uint64_t(b[j])<<(8*j);return n;};if(read()!=1891714||read()!=1891715)throw std::runtime_error("NASA source count");std::vector<Record> v;v.reserve(1891714);for(std::uint64_t j=1;j<=1891714;++j){auto t=read(),row=read();if(t>=domain.span||row!=j)throw std::runtime_error("NASA physical identity");v.push_back({t*domain.stride+row,row});}char extra;if(in.get(extra))throw std::runtime_error("NASA trailing bytes");s1::require_sha(p,sha);return v;}
inline std::vector<Record> ref_range(const std::map<std::uint64_t,std::uint64_t>& ref,std::uint64_t lo,std::uint64_t hi){std::vector<Record> out;for(auto it=ref.lower_bound(lo);it!=ref.end()&&it->first<hi;++it)out.emplace_back(*it);return out;}
inline void geometry(Bundle& b){auto& t=b.whole;std::array<std::size_t,4096> loads{};std::uint64_t prior=UINT64_MAX;for(auto r:t.initial){auto time=r.first/domain.stride;if(time!=prior){++t.initial_distinct_times;prior=time;}++loads[domain.slot(r.first)];}for(auto n:loads){t.initial_nonempty_buckets+=n>0;t.initial_max_bucket=std::max(t.initial_max_bucket,std::uint64_t(n));}t.initmax=t.initial.back().first/domain.stride;}
inline void apply(Bundle& b,PhaseSegment& seg,Step& st,std::map<std::uint64_t,std::uint64_t>& ref){auto& t=b.whole;auto it=ref.find(st.erased);if(it==ref.end())throw std::runtime_error("erase is not current live");if(it==ref.begin()||domain.slot(std::prev(it)->first)!=domain.slot(st.erased))++t.head_erases;ref.erase(it);it=ref.lower_bound(st.added.first);if(it==ref.end()||domain.slot(it->first)!=domain.slot(st.added.first))++t.tail_inserts;if(!ref.insert(st.added).second)throw std::runtime_error("inserted identity already live");if(st.query){auto answer=ref_range(ref,st.lo,st.hi);st.expected_hash=udriver::hash_records(answer);st.expected_count=answer.size();++t.queries;t.returned+=answer.size();++seg.queries;seg.returned+=answer.size();seg.query_hash=udriver::mix(seg.query_hash,st.expected_hash);}seg.request_hash=udriver::phase_mix_step(seg.request_hash,st);t.hash=udriver::phase_mix_step(t.hash,st);t.steps.push_back(st);}
inline Bundle generate(std::vector<Record> source,const std::string& id,unsigned seed,const std::string& profile,std::size_t n,const std::string& proto){validate_case(id);validate_profile(profile,seed);if(!n||n>SIZE_MAX/5||source.size()<5*n)throw std::invalid_argument("source too small for N+4N");std::set<std::uint64_t> rows;for(auto r:source){valid_record(r);if(!rows.insert(r.second).second)throw std::runtime_error("duplicate physical ordinal");}std::sort(source.begin(),source.end());Bundle b;b.domain=domain;b.source_rows=source.size();auto& rq=b.request;rq.initial=n;rq.units=4*n;rq.seed=seed;rq.workload=id;rq.month="S2:"+profile;rq.days=31;rq.dataset_sha=source_sha;rq.protocol_sha=proto;b.ordered=id!="L03";b.query_period=256;b.cancel_period=id=="L01"?0:256;auto& t=b.whole;
 std::mt19937_64 start(7817329ULL+std::uint64_t(seed)*104729),cancel(0x81ec39b7526a04dfULL^(std::uint64_t(seed)*104729)),shuffle(0x35710df29a48b6ceULL+std::uint64_t(seed)*130363);std::uniform_int_distribution<std::uint64_t> choose_start(0,source.size()-5*n);t.start=choose_start(start);t.initial.assign(source.begin()+t.start,source.begin()+t.start+n);geometry(b);t.hash=udriver::mix(t.hash,udriver::hash_records(t.initial));std::map<std::uint64_t,std::uint64_t> ref(t.initial.begin(),t.initial.end());
 // Slots follow sorted complete keys and cover initial plus every future insertion.
 Fenwick alive(5*n);std::vector<unsigned char> flags(5*n);for(std::size_t j=0;j<n;++j){alive.add(j,1);flags[j]=1;}
 std::vector<std::size_t> lengths=id=="L03"?std::vector<std::size_t>{4*n/3,4*n/3,4*n-2*(4*n/3)}:std::vector<std::size_t>{4*n};std::size_t begin=0;auto water=t.initmax;
 for(std::size_t phase=0;phase<lengths.size();++phase){PhaseSegment seg;seg.begin=begin;seg.end=begin+lengths[phase];seg.name=id=="L03"?(phase==0?"sparse_before":phase==1?"shuffle":"sparse_after"):id;seg.query_period=id=="L03"&&phase==1?8:256;seg.cancel_period=id=="L01"||(id=="L03"&&phase==1)?0:256;seg.random_every_delete=seg.shuffle_incoming=id=="L03"&&phase==1;std::vector<std::size_t> incoming(lengths[phase]);std::iota(incoming.begin(),incoming.end(),n+begin);if(seg.shuffle_incoming)std::shuffle(incoming.begin(),incoming.end(),shuffle);
  for(std::size_t local=0;local<incoming.size();++local){auto pos=alive.select(0);if(seg.random_every_delete||(seg.cancel_period&&(local+1)%seg.cancel_period==0)){std::uniform_int_distribution<std::size_t> rank(0,alive.size()-1);pos=alive.select(rank(cancel));}if(!flags[pos])throw std::logic_error("Fenwick dead rank");flags[pos]=0;alive.add(pos,-1);auto added=incoming[local];if(flags[added])throw std::logic_error("incoming reused");flags[added]=1;alive.add(added,1);Step st;st.erased=source[t.start+pos].first;st.added=source[t.start+added];water=std::max(water,st.added.first/domain.stride);st.query=(local+1)%seg.query_period==0;if(st.query){st.hi=(water+1)*domain.stride;st.lo=(water+1>60?water+1-60:0)*domain.stride;}apply(b,seg,st,ref);if(ref.size()!=n||alive.size()!=n)throw std::logic_error("fixed live N");}b.segments.push_back(seg);begin=seg.end;}
 t.final.assign(ref.begin(),ref.end());t.hash=udriver::mix(t.hash,udriver::hash_records(t.final));return b;}
inline Bundle prefix(const Bundle& longest,std::size_t units){if(units!=longest.request.initial&&units!=2*longest.request.initial&&units!=4*longest.request.initial)throw std::invalid_argument("S2 horizon rejected");Bundle b=longest;auto& t=b.whole;t.steps.clear();t.final.clear();t.hash=udriver::mix(udriver::phase_hash_basis,udriver::hash_records(t.initial));t.queries=t.returned=t.head_erases=t.tail_inserts=0;b.request.units=units;b.segments.clear();std::map<std::uint64_t,std::uint64_t> ref(t.initial.begin(),t.initial.end());for(auto seg:longest.segments){if(seg.begin>=units)break;seg.end=std::min(seg.end,units);seg.queries=seg.returned=0;seg.query_hash=seg.request_hash=udriver::phase_hash_basis;for(std::size_t j=seg.begin;j<seg.end;++j){auto st=longest.whole.steps[j];apply(b,seg,st,ref);}b.segments.push_back(seg);}t.final.assign(ref.begin(),ref.end());t.hash=udriver::mix(t.hash,udriver::hash_records(t.final));return b;}
inline void validate_bundle(const Bundle& b,bool production=true){auto profile=b.request.month.substr(0,3)=="S2:"?b.request.month.substr(3):"invalid";validate_profile(profile,b.request.seed);validate_case(b.request.workload);auto n=b.request.initial,u=b.request.units;if(!n||u!=b.whole.steps.size()||(u!=n&&u!=2*n&&u!=4*n)||b.whole.initial.size()!=n||b.whole.final.size()!=n||b.domain.stride!=domain.stride||b.domain.span!=domain.span||b.request.days!=31||b.request.dataset_sha!=source_sha)throw std::runtime_error("S2 shape/domain/identity mismatch");if(production&&(b.request.protocol_sha!=protocol_sha||b.source_rows!=1891714||(n!=262144&&!(profile=="engineering"&&n==768))))throw std::runtime_error("S2 registered cache mismatch");if(b.source_rows<5*n||b.whole.start>b.source_rows-5*n)throw std::runtime_error("S2 longest start bound");
 std::map<std::uint64_t,std::uint64_t> ref;std::set<std::uint64_t> seen;for(auto r:b.whole.initial){valid_record(r);if(!seen.insert(r.second).second||!ref.insert(r).second)throw std::runtime_error("S2 initial duplicate");}if(std::vector<Record>(ref.begin(),ref.end())!=b.whole.initial)throw std::runtime_error("S2 initial order");auto water=b.whole.initial.back().first/domain.stride;auto hash=udriver::mix(udriver::phase_hash_basis,udriver::hash_records(b.whole.initial));std::uint64_t queries=0,returned=0;std::size_t begin=0,maxu=4*n,phase=0;
 for(const auto& seg:b.segments){auto expected_end=b.request.workload=="L03"?(phase<2?(phase+1)*(maxu/3):maxu):maxu;auto q=b.request.workload=="L03"&&phase==1?8:256;auto c=b.request.workload=="L01"||(b.request.workload=="L03"&&phase==1)?0:256;bool random=b.request.workload=="L03"&&phase==1;auto name=b.request.workload=="L03"?(phase==0?"sparse_before":phase==1?"shuffle":"sparse_after"):b.request.workload;if(seg.name!=name||seg.begin!=begin||seg.end!=std::min(expected_end,u)||seg.end<=begin||seg.query_period!=std::size_t(q)||seg.cancel_period!=std::size_t(c)||seg.random_every_delete!=random||seg.shuffle_incoming!=random)throw std::runtime_error("S2 original phase/cadence");std::uint64_t ph=udriver::phase_hash_basis,qh=udriver::phase_hash_basis,pq=0,pr=0;
  for(std::size_t j=seg.begin;j<seg.end;++j){auto st=b.whole.steps[j];valid_record(st.added);if(!seen.insert(st.added.second).second||!ref.erase(st.erased))throw std::runtime_error("S2 reuse/erase identity");if(!ref.insert(st.added).second||ref.size()!=n)throw std::runtime_error("S2 live count");water=std::max(water,st.added.first/domain.stride);if(st.query!=((j-seg.begin+1)%q==0))throw std::runtime_error("S2 cadence mismatch");if(st.query){auto lo=(water+1>60?water+1-60:0)*domain.stride,hi=(water+1)*domain.stride;if(st.lo!=lo||st.hi!=hi)throw std::runtime_error("S2 watermark range");auto answer=ref_range(ref,lo,hi);if(answer.size()!=st.expected_count||udriver::hash_records(answer)!=st.expected_hash)throw std::runtime_error("S2 query reference");++queries;++pq;returned+=answer.size();pr+=answer.size();qh=udriver::mix(qh,st.expected_hash);}hash=udriver::phase_mix_step(hash,st);ph=udriver::phase_mix_step(ph,st);}
  if(ph!=seg.request_hash||qh!=seg.query_hash||pq!=seg.queries||pr!=seg.returned)throw std::runtime_error("S2 phase identity");begin=seg.end;++phase;}
 if(begin!=u||queries!=b.whole.queries||returned!=b.whole.returned||std::vector<Record>(ref.begin(),ref.end())!=b.whole.final||udriver::mix(hash,udriver::hash_records(b.whole.final))!=b.whole.hash)throw std::runtime_error("S2 final/hash/count");}
struct CacheDirectory{std::filesystem::path old;explicit CacheDirectory(const std::filesystem::path& d):old(std::filesystem::current_path()){std::filesystem::current_path(d);}~CacheDirectory(){std::filesystem::current_path(old);}};
inline void write_cache(const std::filesystem::path& p,const Bundle& b){auto absolute=std::filesystem::absolute(p);CacheDirectory scope(absolute.parent_path());udriver::write_cache(s1::path_utf8(absolute.filename()),b);}
inline Bundle read_cache(const std::filesystem::path& p,bool registered=true){auto absolute=std::filesystem::absolute(p);CacheDirectory scope(absolute.parent_path());auto b=udriver::read_cache(s1::path_utf8(absolute.filename()));validate_bundle(b,registered);return b;}
inline void write_meta(const std::filesystem::path& p,const Bundle& b,const std::string& cache_sha,const std::string& longest_sha){std::ofstream o(p);o<<"{\"schema\":\"S2.cache.v1\",\"case_id\":"<<quote(b.request.workload)<<",\"profile\":"<<quote(b.request.month.substr(3))<<",\"seed\":"<<b.request.seed<<",\"N\":"<<b.request.initial<<",\"U\":"<<b.request.units<<",\"Umax\":"<<4*b.request.initial<<",\"horizon\":"<<b.request.units/b.request.initial<<",\"start\":"<<b.whole.start<<",\"stride\":"<<domain.stride<<",\"span\":"<<domain.span<<",\"source_rows\":"<<b.source_rows<<",\"source_sha\":"<<quote(source_sha)<<",\"protocol_sha\":"<<quote(b.request.protocol_sha)<<",\"cache_sha\":"<<quote(cache_sha)<<",\"longest_cache_sha\":"<<quote(longest_sha)<<",\"initial_sha\":"<<quote(record_sha(b.whole.initial))<<",\"final_sha\":"<<quote(record_sha(b.whole.final))<<",\"trace_hash\":"<<b.whole.hash<<",\"query_hash\":"<<query_hash(b)<<",\"source_bundle_sha\":"<<quote(source_bundle_sha)<<",\"queries\":"<<b.whole.queries<<",\"returned\":"<<b.whole.returned<<",\"API_calls\":"<<2*b.request.units+b.whole.queries<<",\"engineering_only\":"<<(b.request.month=="S2:engineering"?"true":"false")<<"}\n";o.close();if(!o)throw std::runtime_error("cache metadata write");}
